WITH a AS (SELECT geometria,data_extracao FROM `basedosdados.br_sfb_sicar.app` WHERE data_extracao='2026-08-03' AND id_imovel='MS-5006606-4693892971CF47B4B2684C3A94950BEE'), ag AS (SELECT MAX(data_extracao) data_extracao,ST_UNION_AGG(geometria) geom_app FROM a), i AS (SELECT area,geometria FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao='2026-08-03' AND sigla_uf='MS' AND id_imovel='MS-5006606-4693892971CF47B4B2684C3A94950BEE') SELECT ag.data_extracao,ROUND(ST_AREA(ag.geom_app)/10000,6) area_app_ha,ROUND(i.area,6) area_imovel_ha,ROUND(ST_AREA(ST_INTERSECTION(ag.geom_app,i.geometria))/10000,6) area_intersecao_ha,ROUND(SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(ag.geom_app,i.geometria)),ST_AREA(ag.geom_app))*100,6) percentual_app_intersecta_imovel FROM ag CROSS JOIN i